const rows = $input.all().map(i => i.json);

const available = rows.filter(r => {
  const status = (r.Status || '').toString().trim().toLowerCase();
  const topic = (r.Topic || r.Title || '').toString().trim();
  return topic !== '' && status !== 'published';
});

const selected = available.slice(0, 3);
const topicOf = (r) => (r ? (r.Topic || r.Title || '') : '');

const monday = $now.set({ hour: 10, minute: 0, second: 0, millisecond: 0 });
const wednesday = $now.plus({ days: 2 }).set({ hour: 15, minute: 0, second: 0, millisecond: 0 });
const friday = $now.plus({ days: 4 }).set({ hour: 15, minute: 0, second: 0, millisecond: 0 });

return [{
  json: {
    count: selected.length,
    missingCount: 3 - selected.length,
    hasTopic1: selected.length >= 1,
    hasTopic2: selected.length >= 2,
    hasTopic3: selected.length >= 3,
    topic1: topicOf(selected[0]),
    row1: selected[0] ? selected[0].row_number : null,
    slot1: 'Monday 10:00 AM',
    scheduled1: monday.toISO(),
    topic2: topicOf(selected[1]),
    row2: selected[1] ? selected[1].row_number : null,
    slot2: 'Wednesday 3:00 PM',
    scheduled2: wednesday.toISO(),
    topic3: topicOf(selected[2]),
    row3: selected[2] ? selected[2].row_number : null,
    slot3: 'Friday 3:00 PM',
    scheduled3: friday.toISO(),
  },
}];

let text = $('Generate Post 1').first().json.output || '';

function toBold(str) {
  let out = '';
  for (const ch of str) {
    const code = ch.codePointAt(0);
    if (ch >= 'A' && ch <= 'Z') {
      out += String.fromCodePoint(0x1D400 + (code - 65));
    } else if (ch >= 'a' && ch <= 'z') {
      out += String.fromCodePoint(0x1D41A + (code - 97));
    } else if (ch >= '0' && ch <= '9') {
      out += String.fromCodePoint(0x1D7CE + (code - 48));
    } else {
      out += ch;
    }
  }
  return out;
}

text = text.replace(/\*\*(.+?)\*\*/gs, (m, inner) => toBold(inner));
text = text.replace(/__(.+?)__/gs, (m, inner) => toBold(inner));
text = text.replace(/^\s{0,3}#{1,6}\s+/gm, '');
text = text.replace(/\*+/g, '');
text = text.replace(/\n{3,}/g, '\n\n').trim();

return [{ json: { postText: text } }];

