// Get input from previous node
const inputItem = $input.first().json;
let rawText = inputItem.text || inputItem.content || inputItem;

// If it's a string, clean markdown and parse JSON
if (typeof rawText === 'string') {
  // Remove markdown wrapper if present
  rawText = rawText.replace(/```json|```/g, '').trim();
  try {
    const parsed = JSON.parse(rawText);
    rawText = parsed.qwen_image_prompt || parsed.text || rawText;
  } catch (e) {
    // Fallback if parsing fails
  }
} else if (typeof rawText === 'object') {
  rawText = rawText.qwen_image_prompt || rawText.text || JSON.stringify(rawText);
}

// Return strictly the cleaned image prompt string
return [{
  json: {
    final_image_prompt: rawText
  }
}];

